class signaller;

class signal
{
public:
  signal(const char* name, signaller* owner = 0);
  unsigned int add_callback(void (*fn)(signaller*, const char*), char* parms, bool one_shot = false);
};

class signal_list
{
  char allocator_state[4];
  signal** start;
  signal** finish;
  signal** end_of_storage;
public:
  typedef unsigned int size_t;
  signal*& operator[](size_t index) { return start[index]; }
};

class signaller
{
  unsigned int flags;
  signal_list* signals;
public:
  enum signal_id_t { N_SIGNALS };
  virtual ~signaller();
  virtual bool is_an_entity() const { return false; }
  virtual bool is_a_trigger() const { return false; }
  virtual void raise_signal(signal_list::size_t index) const;
private:
  virtual signal_list* construct_signal_list();
protected:
  virtual const char* get_signal_name(unsigned short index) const;
public:
  signal* signal_ptr(signal_list::size_t idx)
  {
    if (signals == 0)
      signals = construct_signal_list();
    signal_list& sl = *signals;
    if (sl[idx] == 0)
      sl[idx] = new signal(get_signal_name(idx), this);
    return sl[idx];
  }
};

class entity : public signaller
{
public:
  enum signal_id_t
  {
    PARENT_SYNC_DUMMY = signaller::N_SIGNALS - 1,
    ACTIVATED_BY_CHARACTER,
    DAMAGED,
    DESTROYED,
    RADIO_DETONATE,
    USE_ITEM,
    ANIM_ACTION,
    ATTACK_BEGIN,
    ATTACK_END,
    ATTACK,
    FOOTSTEP_L,
    FOOTSTEP_R,
    AI_STATE_IDLE,
    AI_STATE_ALERTED,
    AI_STATE_COMBAT,
    AI_STATE_INCREMENT,
    AI_STATE_DECREMENT,
    AI_BOSS_SIGNAL_1,
    AI_BOSS_SIGNAL_2,
    AI_BOSS_SIGNAL_3,
    AI_BOSS_SIGNAL_4,
    GENERIC_SIGNAL_1,
    GENERIC_SIGNAL_2,
    GENERIC_SIGNAL_3,
    GENERIC_SIGNAL_4,
    FADED_OUT,
    SCENE_ANIM_FINISHED,
    BOUNCED,
    N_SIGNALS
  };

  void add_signal_callbacks();
};

void entity_signal_callback_attack(signaller*, const char*);
void entity_signal_callback_footstep(signaller*, const char*);
void entity_signal_callback_raiser(signaller*, const char*);

void entity::add_signal_callbacks()
{
  signal_ptr(ATTACK)->add_callback(entity_signal_callback_attack, 0);

  signal_ptr(FOOTSTEP_L)->add_callback(entity_signal_callback_footstep, 0);
  signal_ptr(FOOTSTEP_R)->add_callback(entity_signal_callback_footstep, 0);

  for (unsigned short i = 0; i < N_SIGNALS; ++i)
    signal_ptr(i)->add_callback(entity_signal_callback_raiser, (char*)i);
}
